// Keep a list of timestamps for detections in the last WINDOW_MS.
const WINDOW_MS = 60 * 1000; // 60 second window
const now = Date.now();

let times = flow.get('detect_times') || [];
times.push(now);
// Drop anything older than the window.
times = times.filter(t => (now - t) <= WINDOW_MS);
flow.set('detect_times', times);

msg.count = times.length;
msg.window_s = WINDOW_MS / 1000;
return msg;

// Same thresholds as the Python rule-based virtual sensor.
const c = msg.count || 0;
let level;
if (c === 0)       level = 'idle';
else if (c <= 2)   level = 'low';
else if (c <= 5)   level = 'medium';
else               level = 'high';

// Derive bin id from the topic: smartbin/<bin>/<device>/motion
const parts = (msg.topic || '').split('/');
const binId = parts[1] || 'bin-01';

const out = {
    bin_id: binId,
    usage_level: level,
    event_count: c,
    window_s: msg.window_s,
    ts: new Date().toISOString()
};

msg.bin_id = binId;
msg.usage_level = level;
msg.payload = JSON.stringify(out);
msg.topic = `smartbin/${binId}/usage`;
return msg;

const alert = {
    bin_id: msg.bin_id,
    severity: 'warning',
    message: `Bin ${msg.bin_id} usage is HIGH (${msg.count} events/min)`,
    ts: new Date().toISOString()
};
return {
    topic: `smartbin/${msg.bin_id}/alert`,
    payload: JSON.stringify(alert)
};
